using System;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEngine.Rendering;using C2=CrabCityDensityR2;
// Renderer-only, reversible mesh detail. Existing Intact/Fractured/Shard transforms,
// atlas materials and collision descriptors remain owned by the original city loader.
public static class DistrictWorldArtR9 {
 [Serializable]public class Piece{public string asset,tag;public int shard,region,material;public float[] v;public int[] t;}
 [Serializable]public class Adjust{public string asset,piece;public int axis,mode;public float delta;}
 [Serializable]public class Recipe{public Piece[] details,background;public Adjust[] adjustments;}
 static Recipe recipe;static readonly Dictionary<string,Mesh> cache=new Dictionary<string,Mesh>();
 public static int CachedMeshes=>cache.Count;public static float MaximumBoundsExpansion{get;private set;}public static int AppliedVisuals{get;private set;}
 static Recipe Data=>recipe??(recipe=JsonUtility.FromJson<Recipe>(Resources.Load<TextAsset>("WorldArtR9/Recipe").text));
 public static void ApplyBreakable(C2.CityVisualBreakable visual,Shader unused){if(!visual||visual.GetComponent<WorldArtR9Binding>())return;var asset=City2Data.Asset(visual.assetId);if(!Data.details.Any(d=>d.asset==asset.id))return;int region=visual.transform.position.y>18?1:Mathf.Abs(visual.transform.position.x)<28?0:Mathf.Abs(visual.transform.position.x)<135?1:2;var marker=visual.gameObject.AddComponent<WorldArtR9Binding>();foreach(var filter in visual.GetComponentsInChildren<MeshFilter>(true)){int group=-99;for(var parent=filter.transform.parent;parent&&parent!=visual.transform;parent=parent.parent){if(parent==visual.intact.transform){group=-2;break;}if(parent.name.StartsWith("Shard_")){group=int.Parse(parent.name.Substring(6));break;}if(parent==visual.fractured.transform)group=-1;}if(group== -99)continue;string key=asset.id+":"+region+":"+group;Mesh mesh;if(!cache.TryGetValue(key,out mesh)){mesh=BuildAsset(asset,group,region);cache[key]=mesh;}var old=filter.sharedMesh;var a=old.bounds;var b=mesh.bounds;float expansion=Mathf.Max(0,a.min.x-b.min.x,a.min.y-b.min.y,a.min.z-b.min.z,b.max.x-a.max.x,b.max.y-a.max.y,b.max.z-a.max.z);MaximumBoundsExpansion=Mathf.Max(MaximumBoundsExpansion,expansion);if(expansion>.0001f)throw new InvalidOperationException("World detail expanded original render envelope: "+key);marker.filters.Add(filter);marker.originals.Add(old);filter.sharedMesh=mesh;}AppliedVisuals++;}
 public static void RestoreBreakable(C2.CityVisualBreakable visual){var marker=visual?visual.GetComponent<WorldArtR9Binding>():null;if(!marker)return;for(int i=0;i<marker.filters.Count;i++)if(marker.filters[i])marker.filters[i].sharedMesh=marker.originals[i];UnityEngine.Object.Destroy(marker);}
 static Mesh BuildAsset(C2.CityDensityPack.Asset asset,int group,int region){var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();foreach(var p in asset.pieces){if(group!=-2&&p.shard!=group)continue;var points=new Vector3[p.v.Length/3];for(int i=0;i<points.Length;i++)points[i]=new Vector3(p.v[i*3],p.v[i*3+1],p.v[i*3+2]);foreach(var a in Data.adjustments.Where(a=>a.asset==asset.id&&a.piece==p.name)){float min=a.axis<3?points.Min(x=>x[a.axis]):0;for(int i=0;i<points.Length;i++){var x=points[i];if(a.mode==0&&Mathf.Abs(x[a.axis]-min)<.00001f)x[a.axis]+=a.delta;else if(a.mode==1)x[a.axis]+=a.delta;else if(a.mode==2){float radius=Mathf.Sqrt(x.x*x.x+x.z*x.z);if(radius>0){x.x*=Mathf.Max(0,radius-a.delta)/radius;x.z*=Mathf.Max(0,radius-a.delta)/radius;}}points[i]=x;}}
 int start=v.Count;v.AddRange(points);for(int i=0;i<p.uv.Length;i+=2)uv.Add(new Vector2(p.uv[i],p.uv[i+1]));foreach(int t in p.t)tri.Add(start+t);}
 foreach(var d in Data.details.Where(d=>d.asset==asset.id&&d.region==region&&(group==-2||d.shard==group)))Append(d,v,uv,tri,true);var original=asset.pieces.Where(p=>group==-2||p.shard==group).SelectMany(p=>Enumerable.Range(0,p.v.Length/3).Select(i=>new Vector3(p.v[i*3],p.v[i*3+1],p.v[i*3+2]))).ToArray();var bounds=new Bounds(original[0],Vector3.zero);foreach(var point in original)bounds.Encapsulate(point);for(int i=0;i<v.Count;i++){var point=v[i];v[i]=new Vector3(Mathf.Clamp(point.x,bounds.min.x,bounds.max.x),Mathf.Clamp(point.y,bounds.min.y,bounds.max.y),Mathf.Clamp(point.z,bounds.min.z,bounds.max.z));}return MeshFrom(v,uv,tri,"WorldR9 "+asset.id+" "+group+" "+region);}
 static void Append(Piece p,List<Vector3> v,List<Vector2> uv,List<int> tri,bool atlas){int start=v.Count;float u=(p.material%4+.5f)/4,w=(p.material/4+.5f)/4;for(int i=0;i<p.v.Length;i+=3){v.Add(new Vector3(p.v[i],p.v[i+1],p.v[i+2]));uv.Add(atlas?new Vector2(u,w):Vector2.zero);}foreach(int i in p.t)tri.Add(start+i);}
 static Mesh MeshFrom(List<Vector3> v,List<Vector2> uv,List<int> tri,string name){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(v);m.SetUVs(0,uv);m.SetTriangles(tri,0);m.RecalculateNormals();m.RecalculateBounds();return m;}
 public static GameObject BuildBackground(Transform parent,Shader shader){var root=new GameObject("R9 regional depth and atrium");root.transform.SetParent(parent,false);var owner=root.AddComponent<C2.CityDensityOwnedAssets>();Color[] colors={new Color(.55f,.48f,.37f),new Color(.18f,.23f,.25f),new Color(.14f,.34f,.41f),new Color(.70f,.76f,.72f),new Color(.65f,.36f,.13f),new Color(.18f,.40f,.19f)};
 for(int mat=0;mat<6;mat++){var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();foreach(var p in Data.background.Where(p=>p.material==mat))Append(p,v,uv,tri,false);AddAtriumSupports(mat,v,uv,tri);AddLowDistricts(mat,v,uv,tri);var mesh=MeshFrom(v,uv,tri,"R9 background "+mat);owner.meshes.Add(mesh);var material=new Material(shader){color=colors[mat],name="R9 depth material "+mat};if(material.HasProperty("_Metallic"))material.SetFloat("_Metallic",mat==1||mat==2?.3f:0);if(material.HasProperty("_Glossiness"))material.SetFloat("_Glossiness",mat==2?.62f:.2f);owner.materials.Add(material);var obj=new GameObject("R9 regional batch "+mat);obj.transform.SetParent(root.transform,false);obj.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=obj.AddComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;}return root;}
 static void AddAtriumSupports(int mat,List<Vector3> v,List<Vector2> uv,List<int> tri){if(mat!=1&&mat!=3)return;foreach(float side in new[]{-1f,1f}){if(mat==1)foreach(float x in new[]{10f,25,42,60})Box(new Vector3(side*x,27,11.5f),new Vector3(.45f,54,.5f),v,uv,tri);if(mat==3)foreach(var h in new[]{new Vector2(18,27),new Vector2(34,39),new Vector2(51,52)})Box(new Vector3(side*h.x,h.y,12),new Vector3(18,.3f,2),v,uv,tri);}}
 static void AddLowDistricts(int mat,List<Vector3> v,List<Vector2> uv,List<int> tri){foreach(float side in new[]{-1f,1f}){
 // The tall glazed building supports the new upper signs instead of leaving floating props.
 if(mat==2)Box(new Vector3(side*30,30,18.5f),new Vector3(58,60,.28f),v,uv,tri);
 if(mat==1){foreach(float x in new[]{2f,16,30,44,58})Box(new Vector3(side*x,30,18.15f),new Vector3(.35f,60,.45f),v,uv,tri);for(int y=6;y<=60;y+=6)Box(new Vector3(side*30,y,18.08f),new Vector3(58,.22f,.5f),v,uv,tri);}
 foreach(float x in new[]{48f,83,118}){if(mat==2)Box(new Vector3(side*x,6.8f,15),new Vector3(27,13.6f,.3f),v,uv,tri);if(mat==1){foreach(float dx in new[]{-13.5f,-6.75f,0,6.75f,13.5f})Box(new Vector3(side*(x+dx),6.8f,14.7f),new Vector3(.30f,13.6f,.35f),v,uv,tri);foreach(float y in new[]{.25f,6.8f,13.6f})Box(new Vector3(side*x,y,14.65f),new Vector3(27.6f,.25f,.5f),v,uv,tri);}if(mat==3)Box(new Vector3(side*x,6.6f,12),new Vector3(28,.30f,5.5f),v,uv,tri);if(mat==4)foreach(float dx in new[]{-9f,9})Box(new Vector3(side*(x+dx),5.35f,11.8f),new Vector3(5,.38f,.3f),v,uv,tri);if(mat==5)foreach(float dx in new[]{-11f,11})Box(new Vector3(side*(x+dx),1.45f,11.4f),new Vector3(1.6f,1.7f,1.2f),v,uv,tri);}
 }}
 static void Box(Vector3 c,Vector3 s,List<Vector3> v,List<Vector2> uv,List<int> tri){Vector3 a=c-s*.5f,b=c+s*.5f;var p=new Piece{material=1,v=new[]{a.x,a.y,a.z,a.x,b.y,a.z,b.x,b.y,a.z,b.x,a.y,a.z,a.x,a.y,b.z,b.x,a.y,b.z,b.x,b.y,b.z,a.x,b.y,b.z},t=new[]{0,1,2,0,2,3,4,5,6,4,6,7,0,4,7,0,7,1,3,2,6,3,6,5,1,7,6,1,6,2,0,3,5,0,5,4}};Append(p,v,uv,tri,false);}
}
public sealed class WorldArtR9Binding:MonoBehaviour {public readonly List<MeshFilter> filters=new List<MeshFilter>();public readonly List<Mesh> originals=new List<Mesh>();}
public sealed partial class CrabFlightGame {public bool useWorldArtR9=true;}
